// E3 auto-pausa: encaminhar fromMe com conteudo (atendente no app).
// Audio e imagem seguem server-side; n8n nunca baixa nem guarda o binario.
const root = $input.first().json;
const b = root.body || root || {};
const data = b.data || {};
const key = data.key || {};
const event = String(b.event || root.event || '').toLowerCase();
if (event && (event.includes('messages.update') || event.includes('message.ack') || event.includes('reaction'))) return [];
const jid = String(key.remoteJid || '').trim();
const jidAlt = String(key.remoteJidAlt || '').trim();
const instance = String(b.instance || '__INSTANCE__');
const msg = data.message || {};
if (msg.reactionMessage) return [];
const fromMe = Boolean(key.fromMe);
const audio = msg.audioMessage || null;
const imagem = msg.imageMessage || null;
const ehAudio = Boolean(audio);
const ehImagem = Boolean(imagem) && !fromMe;
const texto = msg.conversation || msg.extendedTextMessage?.text || (ehImagem ? String(imagem.caption || '') : '');
const privado = jid.endsWith('@s.whatsapp.net') || jid.endsWith('@lid');
if (!privado || !jid || (!texto && !ehAudio && !ehImagem)) return [];
const jidTelefone = jidAlt.endsWith('@s.whatsapp.net') ? jidAlt : jid;
const telefone = jidTelefone.endsWith('@lid') ? jidTelefone : jidTelefone.split('@')[0];
const destino = jid.endsWith('@lid') ? jid : jid.split('@')[0];
return [{ json: {
  instance, remoteJid: jid, remoteJidAlt: jidAlt, telefone, destino, texto, ehAudio, ehImagem,
  audioMimeType: ehAudio ? String(audio.mimetype || '') : null,
  audioDurationSeconds: ehAudio ? Number(audio.seconds || 0) : null,
  imageMimeType: ehImagem ? String(imagem.mimetype || '') : null,
  imageCaption: ehImagem ? String(imagem.caption || '') : null,
  pushName: data.pushName || '', providerMessageId: String(key.id || ''),
  fromMe
} }];

const resultado = $input.first().json || {};
const origem = $('Extrair1').first().json;
const texto = String(resultado.texto || '').trim();
if (resultado.transcrito === true && texto) {
  return [{ json: { ...origem, texto, audioTranscrito: true, audioFallback: null } }];
}
const fallback = String(resultado.fallback || 'Não consegui entender o áudio. Pode me enviar por texto?').slice(0, 160);
return [{ json: {
  ...origem,
  texto: '[Áudio não transcrito]',
  audioTranscrito: false,
  audioFallback: fallback
} }];

const estado = $input.first().json || {};
const extraida = $('Extrair1').first().json;
const origem = extraida.ehAudio ? $('Aplicar transcricao1').first().json : extraida;
// fromMe e duplicata: para. bot_ativo false NAO para aqui — menu da equipe
// ainda precisa passar; o gate de salvos so deixa cliente se bot_ativo true.
if (origem.fromMe || estado.duplicada === true) return [];
const botAtivo = estado.bot_ativo !== false;
return [{ json: { ...origem, bot_ativo: botAtivo } }];

const chat = $('Consultar contato na Evolution1').first().json || {};
const extraida = $('Extrair1').first().json;
const origem = extraida.ehAudio ? $('Aplicar transcricao1').first().json : extraida;
const rot = $('Rotear operacao1').first().json || {};
const acao = rot.acao;
const botAtivo = origem.bot_ativo !== false;
// Fallback fail-closed se o roteamento nao respondeu.
if (!acao) {
  return (chat.isSaved === false && botAtivo) ? [{ json: { ...origem, acao: 'cliente' } }] : [];
}
// Cliente de vendas so se bot ativo (respeita handoff humano)
if (acao === 'cliente') {
  if (!botAtivo) return [];
  return [{ json: { ...origem, acao } }];
}
if (acao === 'cadastro') {
  return [{ json: { ...origem, acao } }];
}
// Menu e confirmacoes deterministicas: resposta pronta, sem LLM
if (acao === 'cadastro_controle' || acao === 'operacao_controle') {
  const resposta = String(rot.resposta || '').trim();
  if (!resposta) return [];
  return [{ json: { ...origem, acao, audioFallback: resposta, output: resposta } }];
}
return []; // ignorar

const input = typeof query === 'string' ? { termo: query } : (query || {});
const termoRaw = (input.termo ?? input.query ?? '').toString().trim();
const termo = ['', 'todos', 'tudo', 'all', '*'].includes(termoRaw.toLowerCase()) ? '' : termoRaw;
const qs = termo ? { termo } : {};
const resp = await helpers.httpRequest({
  method: 'GET',
  url: 'http://chatbot-api:8000/v1/estoque/buscar',
  qs,
  headers: { Authorization: 'Bearer __CHATBOT_TOKEN__' },
  json: true,
});
return JSON.stringify(resp);

const input = typeof query === 'string' ? { versao_texto: query } : (query || {});
const telefone = (input.telefone || '').toString().trim();
const versao_texto = (input.versao_texto || input.texto || 'aceito').toString().trim();
if (!telefone) return JSON.stringify({ erro: 'telefone obrigatorio' });
const resp = await helpers.httpRequest({
  method: 'POST',
  url: 'http://chatbot-api:8000/v1/consentimentos',
  headers: { Authorization: 'Bearer __CHATBOT_TOKEN__', 'Content-Type': 'application/json' },
  body: {
    telefone,
    versao_texto,
    finalidade: 'simulação e contato da loja',
  },
  json: true,
});
return JSON.stringify(resp);

const input = typeof query === 'string' ? { interesse: query } : (query || {});
const telefone = (input.telefone || '').toString().trim();
if (!telefone) return JSON.stringify({ erro: 'telefone_obrigatorio' });

const nomeRaw = (input.nome || '').toString().trim();
const nomeGenerico = !nomeRaw || ['cliente', 'customer', 'user', 'usuario'].includes(nomeRaw.toLowerCase());

const body = {
  telefone,
  interesse: (input.interesse || '').toString().trim(),
};
if (input.etapa) body.etapa = String(input.etapa).trim();
if (!nomeGenerico) body.nome = nomeRaw;

try {
  const resp = await helpers.httpRequest({
    method: 'POST',
    url: 'http://chatbot-api:8000/v1/leads',
    headers: { Authorization: 'Bearer __CHATBOT_TOKEN__', 'Content-Type': 'application/json' },
    body,
    json: true,
  });
  return JSON.stringify({ ok: true, lead: resp });
} catch (e) {
  const status = e.response?.statusCode || e.statusCode || e.status || null;
  const detail = e.response?.body?.detail || e.message || String(e);
  return JSON.stringify({ ok: false, status, erro: detail });
}

const input = typeof query === 'string' ? {} : (query || {});
const telefone = (input.telefone || '').toString().trim();
const body = {
  cpf: String(input.cpf || ''),
  nascimento: String(input.nascimento || ''),
  entrada: Number(input.entrada ?? 0),
  placa: (input.placa || '').toString().trim(),
  telefone,
};

if (!telefone || !body.placa || !body.cpf || !body.nascimento) {
  return JSON.stringify({
    mensagem: 'Ainda faltam dados para solicitar a simulação.',
  });
}

try {
  const mensagemId = String($('Extrair1').first().json.providerMessageId || '').trim();
  const headers = { Authorization: 'Bearer __CHATBOT_TOKEN__', 'Content-Type': 'application/json' };
  if (mensagemId) headers['Idempotency-Key'] = mensagemId;
  await helpers.httpRequest({
    method: 'POST',
    url: 'http://chatbot-api:8000/v1/simulacoes/solicitar',
    headers,
    body,
    json: true,
    timeout: 10000,
  });
} catch (_) {
  // O vendedor assume mesmo se o serviço de simulação estiver indisponível.
}

try {
  await helpers.httpRequest({
    method: 'PATCH',
    url: `http://chatbot-api:8000/v1/conversas/${encodeURIComponent(telefone)}/estado`,
    headers: { Authorization: 'Bearer __CHATBOT_TOKEN__', 'Content-Type': 'application/json' },
    body: { bot_ativo: false },
    json: true,
  });
} catch (_) {
  // Não expor detalhes internos ao cliente ou ao modelo.
}

return JSON.stringify({
  mensagem: 'Certo, vou preparar a simulação e chamar um vendedor para trazer o resultado para você.',
});

const input = typeof query === 'string' ? { telefone: query } : (query || {});
const telefone = (input.telefone || '').toString().trim();
if (!telefone) return JSON.stringify({ erro: 'telefone obrigatorio' });
const resp = await helpers.httpRequest({
  method: 'PATCH',
  url: `http://chatbot-api:8000/v1/conversas/${encodeURIComponent(telefone)}/estado`,
  headers: { Authorization: 'Bearer __CHATBOT_TOKEN__', 'Content-Type': 'application/json' },
  body: { bot_ativo: false },
  json: true,
});
return JSON.stringify(resp);

const input = typeof query === 'string' ? { placa: query } : (query || {});
const placa = (input.placa || '').toString().trim();
if (!placa) return JSON.stringify({ erro: 'placa obrigatoria' });
const resp = await helpers.httpRequest({
  method: 'GET',
  url: `http://chatbot-api:8000/v1/estoque/por-placa/${encodeURIComponent(placa)}`,
  headers: { Authorization: 'Bearer __CHATBOT_TOKEN__' },
  json: true,
});
return JSON.stringify(resp);

const input = typeof query === 'string' ? {} : (query || {});
const origem = $('Extrair1').first().json;
const telefone_solicitante = String(origem.telefone || '').trim();
const providerMessageId = String(origem.providerMessageId || '').trim();
if (!telefone_solicitante) return JSON.stringify({ erro: 'telefone_solicitante obrigatorio' });

const body = {
  telefone_solicitante,
  tipo: String(input.tipo || 'moto'),
  marca: String(input.marca || ''),
  modelo: String(input.modelo || ''),
  ano_modelo: Number(input.ano_modelo),
  preco: Number(input.preco),
  km: Number(input.km ?? 0),
  placa: String(input.placa || '').trim().toUpperCase(),
};
if (input.versao) body.versao = String(input.versao);
if (input.cor) body.cor = String(input.cor);

const headers = {
  Authorization: 'Bearer __CHATBOT_TOKEN__',
  'Content-Type': 'application/json',
};
if (providerMessageId) headers['Idempotency-Key'] = providerMessageId;

try {
  const resp = await helpers.httpRequest({
    method: 'POST',
    url: 'http://chatbot-api:8000/v1/operacao/veiculos',
    headers,
    body,
    json: true,
  });
  return JSON.stringify({ ok: true, veiculo: resp });
} catch (e) {
  const status = e.response?.statusCode || e.statusCode || e.status || null;
  const detail = e.response?.body?.detail || e.message || String(e);
  return JSON.stringify({ ok: false, status, erro: detail });
}

const input = typeof query === 'string' ? { veiculo_id: query } : (query || {});
const veiculoId = String(input.veiculo_id || '').trim();
if (!/^[A-Za-z0-9-]{1,120}$/.test(veiculoId)) {
  return JSON.stringify({ ok: false, mensagem: 'veiculo_id invalido' });
}

const origem = $('Extrair1').first().json || {};
const destino = String(origem.destino || '').trim();
if (!destino) {
  return JSON.stringify({ ok: false, mensagem: 'destino indisponivel' });
}

try {
  const resolvida = await helpers.httpRequest({
    method: 'GET',
    url: `http://chatbot-api:8000/v1/estoque/veiculos/${encodeURIComponent(veiculoId)}/midia-principal`,
    headers: { Authorization: 'Bearer __CHATBOT_TOKEN__' },
    json: true,
  });
  const midia = resolvida?.midia;
  if (!resolvida?.tem_foto || !midia) {
    return JSON.stringify({ ok: false, sem_foto: true, mensagem: 'Veiculo sem foto cadastrada.' });
  }
  const tipos = { 'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp' };
  const extensao = tipos[midia.content_type];
  const mediaUrl = new URL(String(midia.url || ''));
  if (!extensao || mediaUrl.protocol !== 'https:' || mediaUrl.search || mediaUrl.hash) {
    return JSON.stringify({ ok: false, mensagem: 'Midia indisponivel.' });
  }
  await helpers.httpRequest({
    method: 'POST',
    url: 'http://evolution:8080/message/sendMedia/__INSTANCE__',
    headers: { apikey: '__EVOLUTION_KEY__', 'Content-Type': 'application/json' },
    body: {
      number: destino,
      mediatype: 'image',
      mimetype: midia.content_type,
      caption: 'Foto do veículo consultado',
      media: mediaUrl.toString(),
      fileName: `veiculo-${veiculoId}.${extensao}`,
    },
    json: true,
  });
  return JSON.stringify({ ok: true, mensagem: 'Foto enviada no WhatsApp.' });
} catch (_) {
  return JSON.stringify({ ok: false, mensagem: 'Nao foi possivel enviar a foto agora.' });
}
